previewCss:
.darma-loader-darma-b15-queue-buffer-fill { --accent: var(--loader-color, #0891b2); --accent-2: var(--loader-secondary-color, #f97316); width: var(--loader-size, 136px); height: calc(var(--loader-size, 136px) * .26); position: relative; display: flex; gap: 2.5%; align-items: center; }
.darma-loader-darma-b15-queue-buffer-fill span { flex: 1; height: 100%; border-radius: 4px; background: var(--accent); opacity: .16; transform-origin: 50% 100%; transform: scaleY(.45); animation: darma-loader-darma-b15-queue-buffer-fill-qbuf-cell calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(6) { animation-delay: calc(var(--loader-speed, 1s) * .5); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(7) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b15-queue-buffer-fill span:nth-of-type(8) { animation-delay: calc(var(--loader-speed, 1s) * .7); }
.darma-loader-darma-b15-queue-buffer-fill .darma-loader-darma-b15-queue-buffer-fill__head { position: absolute; top: -14%; bottom: -14%; left: 0; width: 11%; border-radius: 5px; box-shadow: inset 0 0 0 2px var(--accent-2); animation: darma-loader-darma-b15-queue-buffer-fill-qbuf-head calc(var(--loader-speed, 1s) * 2.2) linear infinite; }
@keyframes darma-loader-darma-b15-queue-buffer-fill-qbuf-cell { 0% { opacity: .16; transform: scaleY(.45); } 22%, 62% { opacity: 1; transform: scaleY(1); } 84%, 100% { opacity: .16; transform: scaleY(.45); } }
@keyframes darma-loader-darma-b15-queue-buffer-fill-qbuf-head { 0% { transform: translateX(0); } 100% { transform: translateX(810%); } }

